import {
  calculateHealthCanadaEER,
  calculateInteractiveHousehold,
  calculateBuildingHeatingDemand,
  calculatePersonVisualMetrics,
  calculateLandLeaseAccounting,
  calculateArcCommonAreaGeometry,
  financeCapital,
  defaultBuilding,
  labourCapacityLevels
} from '@living-region/carrying-capacity/browser';
import './style.css';

function renderSectionNavNew() { const links: Array<[string, string]> = [['scenario', '01 Scenario'], ['land-requirement', '02 Land requirement'], ['establishment', '03 Establishment timeline'], ['food', '04 Food requirement'], ['heating', '05 Heating'], ['annual-crops', '06 Annual crops'], ['perennial-crops', '07 Perennial crops'], ['method', '08 Method & sources']]; return `<nav class="section-nav" aria-label="Land and carrying-capacity sections"><span>On this page</span>${links.map(([id, label]) => `<a href="#${id}">${label}</a>`).join('')}</nav>`; }
function renderScenarioSummaryNew(result: any) { const site = state.contract.site_classes[state.site]; const local = site.local_environment ?? {}; const buildingCount = state.buildings.length; const totalFloor = state.buildings.reduce((sum: number, building: Building) => sum + Number(building.floor_area_m2 || 0), 0); return `<div class="scenario-summary"><div class="metric"><span>Household</span><strong>${state.members.length} ${state.members.length === 1 ? 'person' : 'people'}</strong><small>${esc(state.members.map((member) => member.label).join(' · '))}</small></div><div class="metric"><span>Site condition</span><strong>${esc(site.label)}</strong><small>${esc(local.cli_capability_class_band ?? 'Scenario capability band')}</small></div><div class="metric"><span>Heated buildings</span><strong>${buildingCount} · ${fmt(totalFloor, 1)} m²</strong><small>${esc(state.buildings.map((building) => building.label).join(' · '))}</small></div><div class="metric"><span>Local context</span><strong>${fmt(state.contract.environment.climate.growing_degree_days.value_degree_days, 0)} °C·day</strong><small>${fmt(state.contract.environment.climate.frost_free_period.average_length_days, 0)} frost-free days · ${fmt(state.contract.environment.climate.heating_degree_days.value_degree_days, 0)} heating degree days</small></div></div>`; }
function renderScenarioSectionNew(result: any) { const siteOptions: Array<[string, string]> = [['wetter_productive', 'Favourable / productive'], ['ordinary_mesic', 'Ordinary / mesic'], ['dry', 'Dry / moisture-limited'], ['shallow_rocky_marginal', 'Marginal / shallow / rocky']]; const presetOptions: Array<[string, string]> = [['reference_adult_man', 'Reference adult man · editable starting case'], ...state.contract.household_presets.map((row: any) => [row.id, row.label]), ['custom', 'Custom household']]; return `<section class="section" id="scenario"><div class="section-heading"><p class="eyebrow">01 · scenario</p><h2>Choose the household and place</h2><p>Set the people, site condition and heated building load. The result below updates immediately from this scenario.</p></div>${renderScenarioSummaryNew(result)}<div class="controls-row scenario-controls">${selectControl('preset', 'Household', presetOptions, state.preset)}${selectControl('site', 'Site condition', siteOptions, state.site)}</div><p class="small-note">Site bands are transparent scenario capability ranges informed by Owen Sound / Grey County climate and the Ontario soil-capability framework; they are not parcel-level soil classifications.</p></section>`; }
function landComparisonTextNew(establishment: number, mature: number, allocation: number, peakYear: unknown) { const difference = allocation - establishment; const comparison = difference >= 0 ? `leaving the proposed ${area(allocation)} allocation ${area(difference)} above the establishment peak` : `leaving the proposed ${area(allocation)} allocation ${area(Math.abs(difference))} short during establishment`; return `On the selected ${state.contract.site_classes[state.site].label.toLowerCase()} site, this household peaks at ${area(establishment)} in ${peakYear === 'mature' ? 'the mature state' : `Year ${peakYear}`} and settles to ${area(mature)} at maturity, ${comparison}.`; }
function renderDemandScopeNew(result: any) { const profile = result.custom.food_demand_profile ?? {}; const accounting = result.custom.establishment_land?.strategy_comparison?.progressive_handoff; const peak = accounting?.rows?.find((row: any) => row.year === accounting.establishment_peak_year) ?? accounting?.rows?.[0]; const dependentSupplement = peak?.dependent_food_supplement_annual_area_ha ?? 0; return `<div class="demand-scope"><div class="metric"><span>Current household demand</span><strong>${energy(profile.current_household_food_demand_gj_year ?? result.demand)}</strong><small>Adults + currently dependent children</small></div><div class="metric"><span>Permanent adult demand</span><strong>${energy(profile.permanent_adult_food_demand_gj_year ?? result.custom.permanent_adult_food_demand_gj_year)}</strong><small>Sizes the permanent perennial footprint</small></div><div class="metric"><span>Dependent food demand</span><strong>${energy(profile.dependent_child_food_demand_gj_year ?? result.custom.dependent_child_food_demand_gj_year)}</strong><small>Pooled while children remain dependent</small></div><div class="metric"><span>Permanent perennial footprint</span><strong>${area(accounting?.planted_perennial_footprint_ha ?? 0)}</strong><small>Dependent supplement at peak: ${area(dependentSupplement)}</small></div><p class="small-note">Children add to pooled household food demand while dependent, but do not add a permanent perennial allocation to the parental parcel. Annual and perennial food can feed everyone; after adulthood, their long-term allocation is outside this calculation.</p></div>`; }
 function renderLandRequirementNew(result: any) { const custom = result.custom; const accounting = custom.establishment_land?.strategy_comparison?.progressive_handoff; const peak = accounting?.rows?.find((row: any) => row.year === accounting.establishment_peak_year) ?? accounting?.rows?.[0]; const establishment = accounting?.establishment_land_requirement_ha ?? custom.robust_minimum_area_ha; const mature = accounting?.mature_land_requirement_ha ?? custom.robust_minimum_area_ha; const allocation = custom.arc_policy_allocation_ha ?? 0; const difference = allocation - establishment; const parts = peak ? [{id: 'annual', label: 'Annual bridge at peak', area_ha: peak.annual_area_ha}, {id: 'perennial', label: 'Planted perennial footprint', area_ha: peak.planted_perennial_footprint_ha}, {id: 'wood', label: 'Renewable heating biomass', area_ha: peak.heating_area_ha}, {id: 'reserve', label: 'Exclusive resilience reserve', area_ha: peak.exclusive_resilience_reserve_ha}] : custom.land_allocation.parts; return `${renderDemandScopeNew(result)}<div class="land-result"><div class="land-headline-grid"><div class="metric land-primary"><span>Land needed to establish</span><strong>${area(establishment)}</strong><small>Peak requirement from bare land</small></div>${metric('Mature land requirement', area(mature), 'After perennial establishment')}${metric('ARC allocation', area(allocation), 'Policy comparison')}${metric('Establishment surplus / deficit', difference >= 0 ? `+${area(difference)}` : `−${area(Math.abs(difference))}`, difference >= 0 ? 'surplus' : 'deficit')}${metric('Peak year', peak?.year === 'mature' ? 'Mature' : `Year ${peak?.year ?? '—'}`, 'Highest exclusive footprint')}</div><p class="land-interpretation">${esc(landComparisonTextNew(establishment, mature, allocation, peak?.year))}</p><div class="land-breakdown"><div><h3>Peak establishment footprint</h3><div class="allocation"><div class="allocation-bar">${parts.map((part: any) => `<span class="${part.id}" style="width:${Math.max(2, Number(part.area_ha) / Math.max(establishment, .01) * 100)}%" title="${esc(part.label)} ${area(part.area_ha)}"></span>`).join('')}</div><div class="allocation-legend">${parts.map((part: any) => `<span><i class="swatch ${part.id}"></i>${esc(part.label)} <b>${area(part.area_ha)}</b></span>`).join('')}${peak ? `<span><i class="swatch overlap"></i>Valid intercropping overlap <b>−${area(peak.young_forest_annual_intercrop_overlap_ha)}</b></span>` : ''}</div></div></div>${renderLandSvg(result)}</div><div class="housing-note"><h3>Housing density ≠ biological carrying capacity</h3><p>Compact housing can reduce building footprint, roads, utilities and transport distances. Residents still require food, materials and energy. When those flows are imported, the productive land and energy flows occur elsewhere.</p><blockquote>You can concentrate houses. You cannot eliminate the land and energy flows that sustain the people inside them.</blockquote></div></div>`; }
function renderEstablishmentSectionNew(result: any) { const accounting = result.custom.establishment_land?.strategy_comparison?.progressive_handoff; return `<section class="section tinted" id="establishment"><div class="section-heading"><p class="eyebrow">03 · establishment timeline</p><h2>Why the establishment peak is different</h2><p>Perennial land is planted from Year 1, even before it produces much food. Annual bridge acreage then contracts as berries, nuts and fruit systems mature.</p></div><div class="timeline-peak"><strong>Peak year</strong><span>${accounting?.establishment_peak_year === 'mature' ? 'Mature' : `Year ${accounting?.establishment_peak_year ?? '—'}`}</span><small>${area(accounting?.establishment_land_requirement_ha ?? 0)} total exclusive footprint</small></div>${renderTimeline(result)}</section>`; }
function renderFoodSectionNew(result: any) { const food = result.custom.food; return `<section class="section" id="food"><div class="section-heading"><p class="eyebrow">04 · food requirement</p><h2>People → food energy → food area</h2><p>The person variables determine food energy through the canonical Health Canada equation. They do not determine agricultural labour capacity.</p></div><div class="metric-grid four">${metric('Household food energy', energy(result.demand), 'Health Canada EER total')}${metric('Food-production area', area(result.custom.food_area_ha), 'Balanced low-input system')}${metric('Food-adult-equivalent', `${fmt(result.custom.food_adult_equivalents, 2)} FAE`, 'Food-energy normalization only')}${metric('Nutrition screen', food?.macro_range_check?.status ? 'Screening' : 'Available', food?.protein_threshold_met ? 'Protein threshold met' : 'Review protein output')}</div>${renderEnergy(result)}<details class="input-details"><summary>Adjust household members</summary><div class="member-list">${state.members.map(renderMember).join('')}</div><button class="button secondary" data-action="add-member">+ Add household member</button></details></section>`; }
function renderHeatingSectionNew(result: any) { const heating = result.custom.heating; return `<section class="section tinted" id="heating"><div class="section-heading"><p class="eyebrow">05 · heating</p><h2>Buildings → useful heat → woody land</h2><p>Building geometry, envelope, leakage and heater efficiency determine the winter heat load. Each heated building is calculated separately and then summed.</p></div><div class="metric-grid three">${metric('Useful heat', energy(heating.total_useful_heat_gj_year), 'All heated buildings')}${metric('Gross woody energy', energy(heating.total_gross_wood_energy_gj_year), 'Heater efficiency included')}${metric('Woody hectares', area(result.custom.heating_area_ha), 'Selected site productivity')}</div><details class="input-details"><summary>Adjust heated buildings and envelope assumptions</summary>${renderBuildings(result)}</details><details class="input-details"><summary>Check assigned labour capacity</summary>${renderLabour(result)}</details></section>`; }
function annualCropStatusNew(row: any, result: any) { const rule = state.contract.site_classes[state.site].local_environment?.annual_crops?.[row.id]; const selected = result.custom.food?.rows?.find((candidate: any) => candidate.id === row.id); if (rule?.viable === false) return {label: 'Excluded', className: 'excluded', yield: null, role: 'Unsuitable for selected site band'}; if (selected) return {label: 'Selected', className: 'selected', yield: selected.food_gj_ha, role: `${fmt(selected.energy_share * 100, 0)}% of balanced energy mix`}; return {label: 'Viable alternative', className: 'alternative', yield: row.food_gj_ha * Number(rule?.yield_multiplier ?? 1), role: 'Not used in current balanced mix'}; }
function renderAnnualCropsSectionNew(result: any) { const rows = state.contract.food_energy_evidence.rows; return `<section class="section" id="annual-crops"><div class="section-heading"><p class="eyebrow">06 · annual crops</p><h2>Compact annual-crop evidence</h2><p>Annual rows support the bridge while perennial systems establish. Status and effective yield are specific to the selected site band.</p></div><div class="table-scroll"><table class="evidence-table"><thead><tr><th>Crop</th><th>Site status</th><th>Effective yield</th><th>Role</th><th>Evidence</th></tr></thead><tbody>${rows.map((row: any) => { const status = annualCropStatusNew(row, result); return `<tr><th scope="row">${esc(row.crop)}</th><td><span class="status ${status.className}">${status.label}</span></td><td>${status.yield == null ? '—' : `${fmt(status.yield, 1)} GJ/ha`}</td><td>${esc(status.role)}</td><td><details><summary>View</summary><p>${esc(row.category ?? '')} · ${esc(row.evidence_type ?? row.canonical_status ?? 'Evidence row')}</p><p>${sourceLinks(row.source)}</p></details></td></tr>`; }).join('')}</tbody></table></div><p class="small-note">Selected means the row participates in the current balanced food-energy mix. Viable alternatives remain biologically available but are not silently added to the mix.</p><a class="back-top" href="#top">Back to top</a></section>`; }
function perennialStatusNew(row: any) { const capability = state.contract.site_classes[state.site].local_environment?.perennial_layers?.[row.id]; const selected = state.contract.establishment.site_models?.[state.site]?.perennial_mix?.some((candidate: any) => candidate.id === row.id); if (capability?.viable === false) return {label: 'Excluded', className: 'excluded'}; if (String(row.evidence_status).toLowerCase().includes('reference')) return {label: 'Reference only', className: 'reference'}; if (selected) return {label: 'Central synthesis', className: 'selected'}; return {label: 'Viable alternative', className: 'alternative'}; }
function renderPerennialSectionNew() { const evidence = state.contract.perennial_food_evidence; return `<section class="section tinted" id="perennial-crops"><div class="section-heading"><p class="eyebrow">07 · perennial crops</p><h2>Compact perennial evidence</h2><p>These systems provide the mature mix and establish at different rates. Reference-only candidates remain visible without receiving fabricated canonical yields.</p></div><div class="table-scroll"><table class="evidence-table perennial-table"><thead><tr><th>Crop/system</th><th>Model status</th><th>First crop</th><th>Substantial crop</th><th>Mature</th><th>Mature yield</th></tr></thead><tbody>${evidence.rows.map((row: any) => { const status = perennialStatusNew(row); return `<tr><th scope="row">${esc(row.species)}</th><td><span class="status ${status.className}">${status.label}</span></td><td>${row.first_meaningful_crop_year ? `Year ${esc(row.first_meaningful_crop_year)}` : '—'}</td><td>${row.substantial_crop_year ? `Year ${esc(row.substantial_crop_year)}` : '—'}</td><td>${row.mature_year ? `Year ${esc(row.mature_year)}` : '—'}</td><td>${row.mature_yield_t_ha_year == null ? 'Not reported' : `${fmt(row.mature_yield_t_ha_year, 2)} t/ha`}</td></tr><tr class="evidence-detail"><td colspan="6"><details><summary>Evidence and role</summary><p><strong>Role:</strong> ${esc(row.model_role)} · <strong>Food energy:</strong> ${row.mature_food_gj_ha_year == null ? 'Not reported' : `${fmt(row.mature_food_gj_ha_year, 2)} GJ/ha/year`} · <strong>Macros:</strong> ${row.protein_kg_ha == null ? 'Not reported' : `${fmt(row.protein_kg_ha, 1)} protein / ${fmt(row.fat_kg_ha, 1)} fat / ${fmt(row.carbohydrate_kg_ha, 1)} carbohydrate kg/ha`}</p><p>${esc(row.evidence_type)} · ${esc(row.notes)} · ${sourceLinks(row.source)}</p></details></td></tr>`; }).join('')}</tbody></table></div><div class="mix-panel"><h3>Current canonical mature mix</h3><p>${esc(evidence.central_mix.composition)}</p><div class="mix-bar">${evidence.mix.map((row: any) => `<span style="width:${row.area_share * 100}%" title="${esc(row.species)}">${esc(row.species)}</span>`).join('')}</div><div class="metric-grid four">${metric('Mature mix food energy', `${fmt(evidence.central_mix.mature_food_gj_ha_year, 2)} GJ/ha/year`)}${metric('Protein', `${fmt(evidence.central_mix.protein_kg_ha, 1)} kg/ha`)}${metric('Fat', `${fmt(evidence.central_mix.fat_kg_ha, 1)} kg/ha`)}${metric('Carbohydrate', `${fmt(evidence.central_mix.carbohydrate_kg_ha, 1)} kg/ha`)}</div></div><details class="input-details"><summary>Show mature mix timeline and research updates</summary>${renderPerennialTimeline()}<div class="research-updates">${(evidence.research_updates ?? []).map((row: any) => `<p><strong>${esc(row.species)}</strong> · ${esc(row.evidence_status)} · <a href="${esc(row.source)}" target="_blank" rel="noreferrer">source</a><br>${esc(row.finding)} <b>Model action:</b> ${esc(row.canonical_action)}</p>`).join('')}</div></details><a class="back-top" href="#top">Back to top</a></section>`; }
function renderMethodSectionNew() { return `<section class="section" id="method"><div class="section-heading"><p class="eyebrow">08 · method & sources</p><h2>How to read the model</h2><p>The page follows the dependency chain from answer to components to evidence. The calculations remain in the carrying-capacity package; this browser presents its generated contract.</p></div>${renderEnvironment()}<div class="parallel-chain"><div><p class="eyebrow">People</p><strong>age · sex · height · weight · activity</strong><span>→ MJ/day → GJ/year food → food-production area</span></div><div><p class="eyebrow">Buildings</p><strong>floor area · form · RSI · leakage</strong><span>→ GJ/year useful heat → woody-production area</span></div><div><p class="eyebrow">Combined result</p><strong>food + heat + reserve</strong><span>→ peak establishment and mature land requirements</span></div></div><div class="solar-method"><h3>Solar energy is the underlying budget</h3><p>Solar radiation supports photosynthesis, plant biomass, edible food energy and woody fuel. Local numerical solar availability remains unresolved; the model does not invent an insolation value or photosynthetic efficiency.</p><div class="solar-flow"><span>sunlight</span><b>→</b><span>photosynthesis</span><b>→</b><span>edible food energy</span><b>→</b><span>human metabolism</span></div><div class="solar-flow wood"><span>sunlight</span><b>→</b><span>woody biomass</span><b>→</b><span>stored fuel</span><b>→</b><span>winter heat</span></div></div><details class="method" open><summary>Sources, assumptions and uncertainty</summary><div class="source-list">${state.contract.sources.map((source: any) => `<p><strong>${esc(source.institution)} · ${esc(source.title)}</strong><br><span>${esc(source.evidence_status)}</span> · <a href="${esc(source.url)}" target="_blank" rel="noreferrer">source / evidence file</a></p>`).join('')}</div><p class="small-note">Public energy and thermal quantities are metric/SI. Soil capability is a regional scenario framework, not parcel-level mapping. The generated contract retains evidence status and source provenance for detailed rows.</p></details><a class="back-top" href="#top">Back to top</a></section>`; }
function renderCapacityPageNew() { const result = householdResult(); return shell(`<section class="hero capacity-hero" id="top"><div><p class="eyebrow">Land & carrying capacity</p><h1>Land & carrying capacity</h1><p class="lede">Estimate the land required to establish and sustain a household in Owen Sound / Grey County, including food production, perennial establishment, heating biomass and resilience.</p></div><div class="hero-callout"><span>Answer-first model</span><strong>${esc(state.contract.model_version)}</strong><small>Land requirement is calculated before the detailed evidence.</small></div></section>${renderSectionNavNew()}${renderScenarioSectionNew(result)}<section class="section tinted" id="land-requirement"><div class="section-heading"><p class="eyebrow">02 · land requirement</p><h2>How much land does this household need?</h2><p>The primary answer is the peak exclusive footprint from bare land, followed by the mature requirement and the ARC policy comparison.</p></div>${renderLandRequirementNew(result)}<p><a class="button" href="${appUrl('/arc-affordability')}?${scenarioParams(true).toString()}">See what this land allocation costs</a></p></section>${renderEstablishmentSectionNew(result)}${renderFoodSectionNew(result)}${renderHeatingSectionNew(result)}${renderAnnualCropsSectionNew(result)}${renderPerennialSectionNew()}${renderMethodSectionNew()}`, 'capacity'); }

type Member = {id: string; label: string; age_y: number; sex: 'female' | 'male'; weight_kg: number; height_cm: number; activity: string; labour_level: string};
type Building = {id: string; label: string; floor_area_m2: number; archetype: string; insulation: string; envelope?: Record<string, number>};
type Contract = any;

const basePath = import.meta.env.BASE_URL.replace(/\/$/, '');
function appUrl(path: string): string { const clean = path === '/' ? '' : path.replace(/^\/+/, ''); return `${basePath}/${clean}`; }
function routeFromLocation(pathname = window.location.pathname): string { let path = pathname; if (basePath && (path === basePath || path.startsWith(`${basePath}/`))) path = path.slice(basePath.length) || '/'; path = `/${path.replace(/^\/+/, '').replace(/\/+$/, '')}`.replace('//', '/'); return ['/', '/carrying-capacity', '/grey-county-transition', '/arc-affordability'].includes(path) ? path : '/'; }
const state: {contract?: Contract; page: string; site: string; preset: string; members: Member[]; buildings: Building[]; adoption: number; condition: string; mix: string; communitySize: number; arcScenario: string; infrastructureScenario: string; administrationScenario: string; landOwnership: string; landPrice: number; landInterest: number; landAmortization: number; landLoanTerm: number; landDownPayment: number; commonLanewayLength: number} = {page: routeFromLocation(), site: 'ordinary_mesic', preset: 'reference_adult_man', members: [], buildings: [defaultBuilding()], adoption: 25, condition: 'present_external_inputs', mix: 'balanced', communitySize: 12, arcScenario: 'legal_minimum', infrastructureScenario: 'legal_minimum', administrationScenario: 'legal_minimum', landOwnership: 'financed', landPrice: 35000, landInterest: 6, landAmortization: 30, landLoanTerm: 5, landDownPayment: 20, commonLanewayLength: 50};
const sharedQuery = new URLSearchParams(window.location.search);
if (sharedQuery.has('site')) state.site = sharedQuery.get('site') ?? state.site;
if (sharedQuery.has('preset')) state.preset = sharedQuery.get('preset') ?? state.preset;
if (sharedQuery.has('adoption')) state.adoption = Number(sharedQuery.get('adoption')) || state.adoption;
if (sharedQuery.has('condition')) state.condition = sharedQuery.get('condition') ?? state.condition;
if (sharedQuery.has('mix')) state.mix = sharedQuery.get('mix') ?? state.mix;
if (sharedQuery.has('community')) state.communitySize = Number(sharedQuery.get('community')) || state.communitySize;
if (sharedQuery.has('infra')) state.infrastructureScenario = sharedQuery.get('infra') ?? state.infrastructureScenario;
if (sharedQuery.has('admin')) state.administrationScenario = sharedQuery.get('admin') ?? state.administrationScenario;
if (sharedQuery.has('costScenario')) state.arcScenario = sharedQuery.get('costScenario') ?? state.arcScenario;
if (sharedQuery.has('landPrice')) state.landPrice = Number(sharedQuery.get('landPrice')) || state.landPrice;
if (sharedQuery.has('landOwnership')) state.landOwnership = sharedQuery.get('landOwnership') ?? state.landOwnership;
if (sharedQuery.has('landInterest')) state.landInterest = Number(sharedQuery.get('landInterest')) || state.landInterest;
if (sharedQuery.has('landAmortization')) state.landAmortization = Number(sharedQuery.get('landAmortization')) || state.landAmortization;
if (sharedQuery.has('landTerm')) state.landLoanTerm = Number(sharedQuery.get('landTerm')) || state.landLoanTerm;
if (sharedQuery.has('landDownPayment')) state.landDownPayment = Number(sharedQuery.get('landDownPayment')) || state.landDownPayment;
if (sharedQuery.has('lanewayLength')) state.commonLanewayLength = Number(sharedQuery.get('lanewayLength')) || state.commonLanewayLength;
function parseJsonQuery<T>(key: string): T | null { const value = sharedQuery.get(key); if (!value) return null; try { return JSON.parse(value) as T; } catch { return null; } }
const initialMembers = parseJsonQuery<Member[]>('members');
const initialBuildings = parseJsonQuery<Building[]>('buildings');
const $ = (selector: string) => document.querySelector(selector) as HTMLElement | null;
const esc = (value: unknown) => String(value ?? '').replace(/[&<>"']/g, (char) => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;'}[char] ?? char));
const fmt = (value: unknown, digits = 2) => Number.isFinite(Number(value)) ? Number(value).toLocaleString('en-CA', {maximumFractionDigits: digits}) : '—';
const area = (value: unknown) => `${fmt(value, 2)} ha`;
const energy = (value: unknown) => `${fmt(value, 2)} GJ/year`;
const pct = (value: unknown) => `${fmt(value, 1)}%`;

async function loadContract(): Promise<Contract> { const response = await fetch(appUrl('/generated/carrying-capacity/presentation.json')); if (!response.ok) throw new Error(`Contract request failed: ${response.status}`); return response.json(); }
function navigate(path: string) { state.page = routeFromLocation(path); history.pushState({}, '', appUrl(state.page)); render(); }
function scenarioParams(includeEconomics = false) { const params = new URLSearchParams({preset: state.preset, site: state.site}); if (state.preset === 'custom') { params.set('members', JSON.stringify(state.members)); params.set('buildings', JSON.stringify(state.buildings)); } if (includeEconomics) { params.set('community', String(state.communitySize)); params.set('costScenario', state.arcScenario); params.set('infra', state.infrastructureScenario); params.set('admin', state.administrationScenario); params.set('landPrice', String(state.landPrice)); params.set('landOwnership', state.landOwnership); params.set('landInterest', String(state.landInterest)); params.set('landAmortization', String(state.landAmortization)); params.set('landTerm', String(state.landLoanTerm)); params.set('landDownPayment', String(state.landDownPayment)); params.set('lanewayLength', String(state.commonLanewayLength)); } return params; }
function capacityHref() { return `${appUrl('/carrying-capacity')}?${scenarioParams().toString()}#land-requirement`; }
function memberFromProfile(profile: any, index: number): Member { return {id: `member-${Date.now()}-${index}`, label: profile.label ?? `Household member ${index + 1}`, age_y: profile.age_y, sex: profile.sex, weight_kg: profile.weight_kg, height_cm: profile.height_cm, activity: profile.activity, labour_level: Number(profile.age_y) < 19 ? 'dependent' : 'moderate'}; }
function presetMembers(presetId: string): Member[] { const profile = presetId === 'reference_adult_man' ? state.contract.reference_profile : (state.contract.household_presets.find((row: any) => row.id === presetId) ?? state.contract.household_presets[0]); const profiles = profile.members ?? [profile]; return profiles.map((member: any, index: number) => memberFromProfile(member, index)); }
function selectedPreset(): any { return state.contract.household_presets.find((row: any) => row.id === state.preset); }
function resultsForMembers(): any[] { return state.members.map((member) => calculateHealthCanadaEER(member)); }
function isPresetMembers(): boolean { const preset = selectedPreset(); return Boolean(preset && preset.members.length === state.members.length && preset.members.every((member: any, index: number) => member.age_y === state.members[index].age_y && member.sex === state.members[index].sex && member.weight_kg === state.members[index].weight_kg && member.height_cm === state.members[index].height_cm && member.activity === state.members[index].activity)); }
function siteRow(profileId: string, site = state.site): any { return state.contract.mature_rows.find((row: any) => row.household === profileId && row.site === site) ?? state.contract.mature_rows.find((row: any) => row.household === 'two_adults_plus_two_children' && row.site === site); }
function transitionRow(profileId: string, site = state.site): any { return state.contract.transition_rows.find((row: any) => row.household === profileId && row.site === site) ?? state.contract.transition_rows.find((row: any) => row.household === 'two_adults_plus_two_children' && row.site === site); }
function householdResult(): {members: any[]; demand: number; mature: any; custom: any; transition: any} {
  const members = resultsForMembers();
  const preset = selectedPreset();
  const mature = siteRow(isPresetMembers() ? preset.id : 'two_adults_plus_two_children');
  const custom = calculateInteractiveHousehold({members, buildings: state.buildings, siteId: state.site, foodEvidence: state.contract.food_energy_evidence, woodyCases: state.contract.woody_yields.cases, matureReferenceRow: mature, establishmentModel: state.contract.establishment?.site_models?.[state.site]});
  const transition = transitionRow(isPresetMembers() ? preset.id : 'two_adults_plus_two_children');
  return {members, demand: members.reduce((sum, member) => sum + member.gj_year, 0), mature, custom, transition};
}

function shell(content: string, active: string) { if (active === 'affordability') { const infrastructure = state.contract.site_lease_economics.infrastructure_scenarios.filter((row: any) => row.id !== 'legacy_current').map((row: any) => [row.id, row.label] as [string, string]); const affordability = (state.contract.site_lease_economics.affordability_scenarios ?? []).map((row: any) => [row.id, row.label] as [string, string]); const geometry = affordabilityResult(householdResult()).commonAreaGeometry; const geometryPanel = `<div class="common-area-panel"><div class="controls-row affordability-infrastructure-control">${selectControl('affordability-scenario', 'Affordability baseline', affordability, state.arcScenario)}${selectControl('infrastructure', 'Shared infrastructure comparison', infrastructure, state.infrastructureScenario)}<label class="control"><span>Entrance laneway length</span><input id="laneway-length" type="number" min="0" step="5" value="${geometry.inputs.laneway_length_m}"><em>m</em></label></div><details class="method"><summary>Common-area geometry prototype</summary><p>The 50 m default is a configurable conceptual prototype, not a planning-law minimum. Only the physical access corridor, terminal circulation lane, central 250 m² common envelope and explicitly required shared drainage/servicing area are counted as common property.</p><div class="metric-grid four">${metric('Laneway corridor', `${fmt(geometry.laneway.corridor_area_m2, 0)} m²`, `${fmt(geometry.inputs.laneway_length_m, 0)} m × ${fmt(geometry.inputs.common_corridor_width_m, 0)} m`)}${metric('Terminal circulation', `${fmt(geometry.terminal_loop.circulation_lane_area_m2, 0)} m²`, `outer radius ${fmt(geometry.terminal_loop.outer_turning_radius_m, 1)} m`)}${metric('Amenity envelope', `${fmt(geometry.terminal_loop.amenity_envelope_area_m2, 0)} m²`, 'common ground reserved')}${metric('Total common property', `${fmt(geometry.common_property_area_ha, 3)} ha`, 'site-plan validation required')}</div><p class="small-note">Productive shrubs, trees, coppice, windbreaks and other permaculture edges outside vehicle clearances remain in adjoining household leased allocations. Optional amenity-building capital is not included.</p></details></div>`; content = `<div class="mobile-affordability-answer"><span>ARC site and infrastructure charge</span><strong>${cad(affordabilityResult(householdResult()).total)} / month</strong></div>` + geometryPanel + content.replace('<section class="section" id="land-requirement">', '<section class="section" id="land-requirement">'); } return `<header class="topbar"><a class="brand" href="${appUrl('/')}" data-nav>Living Region <span>research interface</span></a><nav><a class="${active === 'capacity' ? 'active' : ''}" href="${appUrl('/carrying-capacity')}" data-nav>Land & capacity</a><a class="${active === 'affordability' ? 'active' : ''}" href="${appUrl('/arc-affordability')}" data-nav>ARC site + infrastructure</a><a class="${active === 'grey' ? 'active' : ''}" href="${appUrl('/grey-county-transition')}" data-nav>Grey County</a></nav></header><main>${content}</main><footer><span>Living Region carrying-capacity contract ${esc(state.contract.model_contract_version)}</span><a href="${appUrl('/carrying-capacity')}#method" data-nav>Sources and method</a></footer>`; }
function sectionHeading(eyebrow: string, title: string, text: string) { return `<div class="section-heading"><p class="eyebrow">${esc(eyebrow)}</p><h2>${esc(title)}</h2><p>${esc(text)}</p></div>`; }
function metric(label: string, value: string, note = '') { return `<div class="metric"><span>${esc(label)}</span><strong>${value}</strong>${note ? `<small>${esc(note)}</small>` : ''}</div>`; }
function selectControl(id: string, label: string, options: Array<[string, string]>, value: string) { return `<label class="control"><span>${esc(label)}</span><select id="${id}">${options.map(([key, text]) => `<option value="${esc(key)}" ${key === value ? 'selected' : ''}>${esc(text)}</option>`).join('')}</select></label>`; }
function memberSelect(index: number, field: string, label: string, options: Array<[string, string]>, value: string) { return `<label class="control"><span>${esc(label)}</span><select data-member="${index}" data-field="${field}">${options.map(([key, text]) => `<option value="${esc(key)}" ${key === value ? 'selected' : ''}>${esc(text)}</option>`).join('')}</select></label>`; }

function renderPersonSvg(member: Member, compact = false) {
  const visual = calculatePersonVisualMetrics(member); const headRadius = visual.age_category === 'child' ? 10 : visual.age_category === 'adolescent' ? 9 : 8; const stroke = visual.age_category === 'child' ? '#d8862e' : visual.age_category === 'older adult' ? '#70507e' : '#176c72';
  return `<svg class="person-figure ${compact ? 'compact' : ''}" viewBox="0 0 80 150" role="img" aria-label="${esc(member.label)}, ${fmt(member.height_cm, 0)} cm and ${fmt(member.weight_kg, 1)} kg"><g transform="translate(40 12) scale(${visual.width_scale} ${visual.height_scale}) translate(-40 -12)"><circle cx="40" cy="${headRadius + 2}" r="${headRadius}" fill="#fbfaf6" stroke="${stroke}" stroke-width="3"/><path d="M40 ${headRadius * 2 + 5} L40 89 M40 38 L20 70 M40 38 L60 70 M40 89 L23 132 M40 89 L57 132" fill="none" stroke="${stroke}" stroke-width="6" stroke-linecap="round"/></g></svg>`;
}
function renderMember(member: Member, index: number) { const labourOptions = Object.entries(labourCapacityLevels).map(([id, row]: any) => [id, row.label] as [string, string]); return `<article class="member-card"><div class="member-title"><strong>Member ${index + 1}</strong><button class="text-button" data-action="remove-member" data-index="${index}" ${state.members.length === 1 ? 'disabled' : ''}>Remove</button></div><div class="member-card-layout"><div class="member-figure-wrap">${renderPersonSvg(member)}<span>${fmt(member.height_cm, 0)} cm · ${fmt(member.weight_kg, 1)} kg</span></div><div class="form-grid four"><label><span>Sex in equation</span><select data-member="${index}" data-field="sex"><option value="female" ${member.sex === 'female' ? 'selected' : ''}>Female</option><option value="male" ${member.sex === 'male' ? 'selected' : ''}>Male</option></select></label><label><span>Age</span><input data-member="${index}" data-field="age_y" type="number" min="3" max="110" step="1" value="${member.age_y}"><em>years</em></label><label><span>Weight</span><input data-member="${index}" data-field="weight_kg" type="number" min="10" max="250" step="0.1" value="${member.weight_kg}"><em>kg</em></label><label><span>Height</span><input data-member="${index}" data-field="height_cm" type="number" min="80" max="230" step="0.1" value="${member.height_cm}"><em>cm</em></label>${memberSelect(index, 'activity', 'Food-energy activity', [['inactive', 'Inactive'], ['low', 'Low'], ['active', 'Active'], ['very', 'Very active']], member.activity)}${memberSelect(index, 'labour_level', 'Assigned productive labour', labourOptions, member.labour_level)}</div></div></article>`; }
function renderHouseholdLineup() { return `<div class="household-lineup"><span class="small-note">Household lineup · illustrative scale cue</span><div>${state.members.map((member) => `<figure>${renderPersonSvg(member, true)}<figcaption>${esc(member.label)}<br>${fmt(member.height_cm, 0)} cm · ${fmt(member.weight_kg, 1)} kg</figcaption></figure>`).join('')}</div></div>`; }
function renderEnergy(result: {members: any[]; demand: number; custom: any}) { return `<div class="metric-grid three">${result.members.map((member) => metric(member.label ?? 'Member', `${fmt(member.mj_day, 2)} MJ/day`, `${fmt(member.gj_year, 2)} GJ/year`)).join('')}${metric('Household food energy', energy(result.demand), 'annual Health Canada EER total')}${metric('Food-adult-equivalent', `${fmt(result.custom.food_adult_equivalents, 2)} FAE`, `${fmt(result.custom.food_adult_equivalent_basis_gj_year, 2)} GJ/year per FAE; food-energy normalization only`)}</div><details class="method"><summary>How this was calculated</summary><p>Each member uses the canonical Health Canada Estimated Energy Requirement equation with sex, age, height, weight and activity. Public energy units are MJ/day and GJ/year. Food-adult-equivalent is a food-energy normalization only and is never multiplied into land requirements.</p><a href="${esc(state.contract.health_canada.source)}" target="_blank" rel="noreferrer">Health Canada source</a></details>`; }

function renderBuilding(building: Building, index: number) {
  const row = calculateBuildingHeatingDemand(building); const archetypes = Object.entries(state.contract.heating.building_archetypes).map(([id, item]: any) => [id, item.label] as [string, string]); const insulation = Object.entries(state.contract.heating.insulation_presets).map(([id, item]: any) => [id, item.label] as [string, string]); const a = row.assumptions;
  const advanced = [['wall_rsi', 'Wall RSI', a.wall_rsi], ['roof_rsi', 'Roof RSI', a.roof_rsi], ['floor_rsi', 'Floor RSI', a.floor_rsi], ['window_u_w_m2k', 'Window U', a.window_u_w_m2k], ['window_area_m2', 'Window area', a.window_area_m2], ['ach', 'Air changes', a.ach], ['indoor_c', 'Indoor temperature', a.indoor_c], ['thermal_bridge', 'Thermal bridge', a.thermal_bridge], ['heater_efficiency', 'Heater efficiency', a.heater_efficiency]];
  return `<article class="building-card"><div class="member-title"><strong>Building ${index + 1}</strong><button class="text-button" data-action="remove-building" data-index="${index}" ${state.buildings.length === 1 ? 'disabled' : ''}>Remove</button></div><div class="form-grid four"><label><span>Label</span><input data-building="${index}" data-field="label" type="text" value="${esc(building.label)}"></label><label><span>Heated floor area</span><input data-building="${index}" data-field="floor_area_m2" type="number" min="5" max="2000" step="0.1" value="${building.floor_area_m2}"><em>m²</em></label>${selectControl(`building-archetype-${index}`, 'Building form', archetypes, building.archetype).replace(`id="building-archetype-${index}"`, `id="building-archetype-${index}" data-building="${index}" data-field="archetype"`)}${selectControl(`building-insulation-${index}`, 'Insulation level', insulation, building.insulation).replace(`id="building-insulation-${index}"`, `id="building-insulation-${index}" data-building="${index}" data-field="insulation"`)}</div><details class="method"><summary>Advanced envelope assumptions</summary><div class="form-grid four advanced-form">${advanced.map(([field, label, value]) => `<label><span>${label}</span><input data-envelope="${index}" data-field="${field}" type="number" min="0" step="0.01" value="${fmt(value, 3)}"><em>${field.includes('rsi') ? 'm²·K/W' : field === 'window_area_m2' ? 'm²' : field === 'window_u_w_m2k' ? 'W·m⁻²·K⁻¹' : field === 'ach' ? '/hour' : field === 'indoor_c' ? '°C' : field === 'thermal_bridge' || field === 'heater_efficiency' ? 'factor' : ''}</em></label>`).join('')}</div><p class="small-note">Presets are explicit assumptions: wall, roof and floor RSI, window U-value/area, air change, indoor temperature, thermal bridge and heater efficiency. ECCC heating-degree data and the design temperature remain fixed model evidence.</p></details></article>`;
}
function renderBuildings(result: any) { return `<div class="building-list">${state.buildings.map(renderBuilding).join('')}</div><button class="button secondary" data-action="add-building">+ Add heated building</button><div class="building-summary"><div class="metric-grid three">${result.custom.heating.buildings.map((row: any) => metric(row.building.label, energy(row.heat_loss.annual_useful_space_heating_gj), `${fmt(row.heat_loss.total_ua_w_k, 1)} W/K`)).join('')}${metric('Total useful heat', energy(result.custom.heating.total_useful_heat_gj_year), 'all heated buildings')}${metric('Gross woody energy', energy(result.custom.heating.total_gross_wood_energy_gj_year), 'heater efficiency included')}${metric('Woody hectares', area(result.custom.heating_area_ha), 'selected site band')}</div><details class="method"><summary>How building heat becomes woody land</summary><p>Each building is solved from its geometry and envelope. Useful heat is converted to gross woody energy using heater efficiency, then divided by the selected canonical woody productivity band. Adding a community building therefore adds a distinct heat load.</p></details></div>`; }
function renderLabour(result: any) { const labour = result.custom.labour; return `<div class="labour-panel"><div class="metric-grid four">${metric('Recurring work required', `${fmt(labour.required_hours_year, 0)} hours/year`)}${metric('Physically demanding work', `${fmt(labour.required_heavy_hours_year, 0)} hours/year`)}${metric('Assigned capacity', `${fmt(labour.available_hours_year, 0)} hours/year`)}${metric('Capacity surplus/deficit', `${fmt(labour.surplus_hours_year, 0)} hours/year`, labour.surplus_hours_year >= 0 ? 'surplus' : 'deficit')}</div><div class="metric-grid two">${metric('Heavy-work capacity', `${fmt(labour.available_heavy_hours_year, 0)} hours/year`)}${metric('Heavy-work surplus/deficit', `${fmt(labour.surplus_heavy_hours_year, 0)} hours/year`, labour.surplus_heavy_hours_year >= 0 ? 'surplus' : 'deficit')}</div><p class="small-note">Food demand and labour capacity are separate. A person’s sex, weight, height and food-energy activity do not infer their agricultural capability; each person receives an explicit labour assignment above.</p></div>`; }

function renderEnvironment() { const environment = state.contract.environment; const site = state.contract.site_classes[state.site]; const climate = environment.climate; const capability = site.local_environment ?? {}; const precip = climate.precipitation ?? {}; const frost = climate.frost_free_period ?? {}; return `<section class="environment-panel"><div class="section-heading"><p class="eyebrow">Local growing environment</p><h3>Owen Sound / Grey County context</h3><p>${esc(capability.description ?? site.notes)} The bands are scenario capability classes informed by the regional climate and the Ontario soil-capability framework; they are not parcel-level soil mapping.</p></div><div class="metric-grid four">${metric('Growing degree days', `${fmt(climate.growing_degree_days?.value_degree_days, 0)} °C·day`, 'base 5 °C')}${metric('Frost-free period', `${fmt(frost.average_length_days, 0)} days`)}${metric('Annual precipitation', `${fmt(precip.annual_mm, 0)} mm`)}${metric('Heating degree days', `${fmt(climate.heating_degree_days?.value_degree_days, 0)} °C·day`, 'base 18 °C')}</div><div class="metric-grid four">${metric('Growing-season precipitation', `${fmt(precip.growing_season_mm, 0)} mm`, 'May–October')}${metric('Soil capability range', `CLI ${esc(capability.cli_class_range ?? '—')}`)}${metric('Drainage', esc(capability.drainage ?? '—'))}${metric('Water constraint', esc(capability.moisture_constraint ?? '—'))}</div><p class="small-note"><strong>Selected crops:</strong> ${esc((capability.annual_crops ? Object.entries(capability.annual_crops).filter(([, row]: any) => row.viable !== false).map(([id]) => id.replaceAll('_', ' ')).join(', ') : '—'))}. <strong>Excluded as unsuitable:</strong> ${esc((capability.annual_crops ? Object.entries(capability.annual_crops).filter(([, row]: any) => row.viable === false).map(([id]) => id.replaceAll('_', ' ')).join(', ') || 'none' : '—'))}. Local numerical solar availability remains unresolved: the model does not invent an insolation value.</p><details class="method"><summary>Environmental sources and uncertainty</summary><p>${esc(environment.sources?.map((source: any) => `${source.institution}: ${source.title} (${source.source_date}; ${source.evidence_status})`).join(' · ') ?? 'See the generated environment contract.')}</p><p>${esc(environment.soil_framework?.caveat ?? 'Parcel-level soil capability remains a later GIS integration.')}</p></details></section>`; }

function renderLandSvg(result: any) { const accounting = result.custom.establishment_land?.strategy_comparison?.progressive_handoff; const row = accounting?.rows?.find((item: any) => item.year === accounting.establishment_peak_year) ?? accounting?.rows?.[0]; const parts = row ? [{id: 'annual', label: 'Annual bridge', area_ha: row.annual_area_ha}, {id: 'perennial', label: 'Planted perennial', area_ha: row.planted_perennial_footprint_ha}, {id: 'wood', label: 'Woody heating', area_ha: row.heating_area_ha}, {id: 'reserve', label: 'Exclusive reserve', area_ha: row.exclusive_resilience_reserve_ha}] : result.custom.land_allocation.parts; const total = accounting?.establishment_land_requirement_ha ?? result.custom.robust_minimum_area_ha; const max = Math.max(total, .01); let x = 20; const segments = parts.map((part: any) => { const width = Math.max(8, 360 * part.area_ha / max); const svg = `<rect x="${x}" y="28" width="${width}" height="150" class="land-${part.id}"/><text x="${x + width / 2}" y="105" text-anchor="middle">${part.area_ha >= .06 ? esc(part.label) : ''}</text>`; x += width; return svg; }).join(''); const overlap = row?.young_forest_annual_intercrop_overlap_ha ?? 0; return `<div class="land-visual"><svg viewBox="0 0 400 220" role="img" aria-label="Bare-land establishment area with a valid intercropping overlap"><defs><pattern id="overlay-hatch" width="8" height="8" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><line x1="0" y1="0" x2="0" y2="8" stroke="#ffffff" stroke-width="2" opacity=".55"/></pattern></defs>${segments}<rect x="20" y="28" width="360" height="150" class="land-overlay" fill="url(#overlay-hatch)"/><text x="200" y="202" text-anchor="middle">${fmt(total, 2)} ha peak exclusive footprint</text></svg><p class="small-note">Peak year ${esc(accounting?.establishment_peak_year ?? '—')}: annual bridge + planted perennial − ${fmt(overlap, 2)} ha valid overlap + heating + exclusive reserve. Ecological overlays are not extra hectares.</p></div>`; }
function renderLand(result: any) { const custom = result.custom; const accounting = custom.establishment_land?.strategy_comparison?.progressive_handoff; const peak = accounting?.rows?.find((row: any) => row.year === accounting.establishment_peak_year) ?? accounting?.rows?.[0]; const parts = peak ? [{id: 'annual', label: 'Annual bridge at peak', area_ha: peak.annual_area_ha}, {id: 'perennial', label: 'Planted perennial footprint', area_ha: peak.planted_perennial_footprint_ha}, {id: 'wood', label: 'Renewable heating biomass', area_ha: peak.heating_area_ha}, {id: 'reserve', label: 'Exclusive resilience reserve', area_ha: peak.exclusive_resilience_reserve_ha}] : custom.land_allocation.parts; const establishment = accounting?.establishment_land_requirement_ha ?? custom.robust_minimum_area_ha; const mature = accounting?.mature_land_requirement_ha ?? custom.robust_minimum_area_ha; const allocation = custom.arc_policy_allocation_ha ?? 0; const deficit = allocation - establishment; return `${renderEnvironment()}<div class="allocation"><div class="allocation-bar">${parts.map((part: any) => `<span class="${part.id}" style="width:${Math.max(2, Number(part.area_ha) / Math.max(establishment, .01) * 100)}%" title="${esc(part.label)} ${area(part.area_ha)}"></span>`).join('')}</div><div class="allocation-legend">${parts.map((part: any) => `<span><i class="swatch ${part.id}"></i>${esc(part.label)} <b>${area(part.area_ha)}</b></span>`).join('')}${peak ? `<span><i class="swatch overlap"></i>Valid intercropping overlap <b>−${area(peak.young_forest_annual_intercrop_overlap_ha)}</b></span>` : ''}</div></div>${renderLandSvg(result)}<div class="metric-grid four">${metric('Land needed to establish', area(establishment), 'peak from bare land')}${metric('Mature land requirement', area(mature), 'after perennial establishment')}${metric('ARC allocation', area(allocation), deficit >= 0 ? `${area(deficit)} surplus at establishment` : `${area(Math.abs(deficit))} deficit at establishment`)}${metric('Optional productive surplus', area(result.mature?.additional_productive_surplus_area_ha ?? 0), 'separate from household minimum')}</div><details class="method"><summary>How this was calculated</summary><p>The perennial footprint is planted at the beginning and is sized from the mature viable mix. Each year, annual bridge area supplies the residual food requirement. Young-row intercropping is subtracted once where it is legitimate. The peak exclusive footprint is the establishment planning number; ARC allocation is compared only afterward.</p></details>`; }
function renderTimeline(result: any) { const rows = result.custom.establishment_land?.strategy_comparison?.progressive_handoff?.rows ?? result.transition?.rows ?? []; return `<div class="timeline">${rows.map((row: any) => `<div class="timeline-row"><strong>${row.year === 'mature' ? 'Mature' : `Year ${row.year}`}</strong><span class="bar-track"><i class="annual" style="width:${Math.min(100, Number(row.annual_area_ha ?? row.annual_food_area_ha) * 80)}%"></i><i class="perennial" style="width:${Math.min(100, Number(row.planted_perennial_footprint_ha ?? row.perennial_area_ha ?? row.perennial_food_area_ha) * 28)}%"></i></span><span>${area(row.annual_area_ha ?? row.annual_food_area_ha)} annual bridge / ${area(row.planted_perennial_footprint_ha ?? row.perennial_area_ha ?? row.perennial_food_area_ha)} planted perennial · ${area(row.occupied_food_production_area_ha)} occupied food footprint · ${energy(Number(row.total_usable_food_gj ?? row.annual_food_supplied_gj_year ?? 0) + Number(row.perennial_usable_food_gj ?? row.perennial_food_supplied_gj_year ?? 0))}</span><small>${fmt(row.young_forest_annual_intercrop_overlap_ha ?? 0, 2)} ha valid intercropping overlap · ${area(row.total_exclusive_land_requirement_ha ?? 0)} total exclusive</small></div>`).join('')}</div><div class="small-note">The perennial footprint occupies land in year 1 even before it produces food. Annual bridge acreage falls as perennial output rises; intercropping is subtracted once rather than counted as a second land area.</div>`; }
function renderFoodChart() { const rows = state.contract.food_energy_evidence.rows.filter((row: any) => row.food_gj_ha).sort((a: any, b: any) => b.food_gj_ha - a.food_gj_ha); const max = Math.max(...rows.map((row: any) => row.food_gj_ha)); return `<div class="yield-chart">${rows.map((row: any) => `<div class="yield-row"><span>${esc(row.crop)}</span><div><i style="width:${row.food_gj_ha / max * 100}%"></i></div><b>${fmt(row.food_gj_ha, 1)} GJ/ha</b></div>`).join('')}</div><p class="small-note">These are a balanced low-input evidence set, not a choice of the single highest-energy crop. Each row carries its source and evidence status in the generated contract.</p>`; }
function sourceLinks(source: string) { return String(source ?? '').split(';').map((url) => url.trim()).filter(Boolean).map((url) => `<a href="${esc(url)}" target="_blank" rel="noreferrer">source</a>`).join(' · '); }
function renderPerennialEvidence() { const evidence = state.contract.perennial_food_evidence; const rows = evidence.rows; const max = Math.max(...rows.map((row: any) => Number(row.mature_food_gj_ha_year) || 0), 1); return `<section class="section tinted perennial-section">${sectionHeading('04 · perennial evidence', 'Perennial Food Production', 'These rows are separate from annual crops. Numeric yields are shown only where the canonical evidence contract supports them; reference-only candidates remain visibly uncredited.') }<div class="perennial-grid">${rows.map((row: any) => `<article class="perennial-card ${row.evidence_status === 'reference only' ? 'reference-only' : ''}"><div class="perennial-card-head"><h3>${esc(row.species)}</h3><span class="evidence-badge">${esc(row.evidence_status)}</span></div><div class="perennial-bar"><i style="width:${Math.max(2, (Number(row.mature_food_gj_ha_year) || 0) / max * 100)}%"></i></div><div class="metric-grid three">${metric('First meaningful crop', row.first_meaningful_crop_year ? `Year ${esc(row.first_meaningful_crop_year)}` : 'Not established')}${metric('Substantial crop', row.substantial_crop_year ? `Year ${esc(row.substantial_crop_year)}` : 'Not established')}${metric('Mature year', row.mature_year ? `Year ${esc(row.mature_year)}` : 'Not established')}${metric('Mature yield', row.mature_yield_t_ha_year == null ? 'Not reported' : `${fmt(row.mature_yield_t_ha_year, 2)} t/ha`)}${metric('Food energy', row.mature_food_gj_ha_year == null ? 'Not reported' : energy(row.mature_food_gj_ha_year).replace('GJ/year', 'GJ/ha/year'))}${metric('Protein / fat / carbohydrate', row.protein_kg_ha == null ? 'Not reported' : `${fmt(row.protein_kg_ha, 1)} / ${fmt(row.fat_kg_ha, 1)} / ${fmt(row.carbohydrate_kg_ha, 1)} kg/ha`)}</div><p class="small-note"><strong>Model role:</strong> ${esc(row.model_role)}<br><strong>Evidence:</strong> ${esc(row.evidence_type)} · ${sourceLinks(row.source)}</p><details class="method"><summary>Evidence and caveat</summary><p>${esc(row.notes)}</p><p>${esc(row.climate_or_site)}</p></details></article>`).join('')}</div><div class="mix-panel"><h3>Current canonical mature mix</h3><p>${esc(evidence.central_mix.composition)}</p><div class="mix-bar">${evidence.mix.map((row: any) => `<span style="width:${row.area_share * 100}%" title="${esc(row.species)}">${esc(row.species)}</span>`).join('')}</div><div class="metric-grid four">${metric('Mature mix food energy', energy(evidence.central_mix.mature_food_gj_ha_year).replace('GJ/year', 'GJ/ha/year'))}${metric('Protein', `${fmt(evidence.central_mix.protein_kg_ha, 1)} kg/ha`)}${metric('Fat', `${fmt(evidence.central_mix.fat_kg_ha, 1)} kg/ha`)}${metric('Carbohydrate', `${fmt(evidence.central_mix.carbohydrate_kg_ha, 1)} kg/ha`)}</div></div><div class="research-updates"><h3>Evidence updates and research boundary</h3>${(evidence.research_updates ?? []).map((row: any) => `<p><strong>${esc(row.species)}</strong> · ${esc(row.evidence_status)} · <a href="${esc(row.source)}" target="_blank" rel="noreferrer">source</a><br>${esc(row.finding)} <b>Model action:</b> ${esc(row.canonical_action)}</p>`).join('')}</div></section>`; }
function renderPerennialTimeline() { const timeline = state.contract.perennial_food_evidence.mix_timeline; return `<div class="perennial-timeline">${timeline.map((row: any) => `<article><strong>${row.year === 'mature' ? 'Mature' : `Year ${row.year}`}</strong><b>${fmt(row.harvested_food_gj_year, 1)} GJ/ha/year</b><span>${fmt(row.productive_area_ha, 2)} ha producing of ${fmt(row.area_ha, 0)} ha planted</span><div class="stacked-mix">${row.layers.map((layer: any, index: number) => `<i class="mix-${index}" style="width:${layer.area_share * 100}% ; opacity:${Math.max(.12, layer.maturity_factor)}" title="${esc(layer.species)}"></i>`).join('')}</div><small>${row.layers.map((layer: any) => `${esc(layer.species)} ${fmt(layer.maturity_factor * 100, 0)}%`).join(' · ')}</small></article>`).join('')}</div>`; }

function renderCapacityPageLegacy() {
  const result = householdResult();
  const siteOptions: Array<[string, string]> = [['wetter_productive', 'Favourable / productive'], ['ordinary_mesic', 'Ordinary / mesic'], ['dry', 'Dry / moisture-limited'], ['shallow_rocky_marginal', 'Marginal / shallow / rocky']];
  const presetOptions: Array<[string, string]> = [['reference_adult_man', 'Reference adult man · editable starting case'], ...state.contract.household_presets.map((row: any) => [row.id, row.label])];
  return shell(`<section class="hero"><div><p class="eyebrow">Land & carrying capacity</p><h1>Land is a solar-energy budget.</h1><p class="lede">Explore two linked but distinct physical chains: people require food energy, while buildings require useful heat. Together with perennial transition and reserve, they define a bare-land establishment requirement and a separate mature requirement.</p></div><div class="hero-callout"><span>Canonical model</span><strong>${esc(state.contract.model_version)}</strong><small>Same calculations feed Living Region reports and this interface.</small></div></section><section class="section split"><div>${sectionHeading('01 · people', 'Start with a household', 'The reference adult man is an editable education case, not a claim about an average Grey County resident.')}${selectControl('preset', 'Household preset', presetOptions, state.preset)}<div class="member-list">${state.members.map(renderMember).join('')}</div>${renderHouseholdLineup()}<button class="button secondary" data-action="add-member">+ Add household member</button></div><aside class="sticky-panel"><p class="eyebrow">People → food</p>${renderEnergy(result)}</aside></section><section class="section tinted"><div class="parallel-chain"><div><p class="eyebrow">People</p><strong>age · sex · height · weight · activity</strong><span>→ MJ/day → GJ/year food → food-production area</span></div><div><p class="eyebrow">Buildings</p><strong>floor area · form · RSI · leakage</strong><span>→ GJ/year useful heat → woody energy → woody-production area</span></div><div><p class="eyebrow">Combined result</p><strong>food + heat + reserve</strong><span>→ robust productive land, with ecological functions overlapping rather than adding again</span></div></div><div class="controls-row">${selectControl('site', 'Site condition band', siteOptions, state.site)}</div><p class="small-note">Site bands are transparent scenario capability ranges, not cadastral soil classifications for a particular property.</p></section><section class="section split"><div>${sectionHeading('02 · buildings', 'Buildings are first-class heating loads', 'Assign one or more heated buildings to the household or community. Each load is solved from its own geometry and envelope.')}${renderBuildings(result)}</div><aside class="sticky-panel"><p class="eyebrow">Buildings → winter heat</p>${renderLabour(result)}<details class="method" open><summary>Building load chain</summary><p>Building geometry and envelope produce a heat-loss coefficient in W/K. ECCC heating-degree data and indoor temperature produce useful annual heat; heater efficiency then determines gross woody energy and site woody hectares.</p></details></aside></section><section class="section"><div class="section-heading"><p class="eyebrow">03 · annual evidence</p><h2>Why yields differ</h2><p>Different annual crops emphasize starch, protein, fat or diversity. The canonical balanced system does not select a single highest-energy crop.</p></div>${renderFoodChart()}</section>${renderPerennialEvidence()}<section class="section tinted split"><div><div class="section-heading"><p class="eyebrow">05 · succession</p><h2>Annual → perennial food forest</h2><p>Annual crops provide immediate food while perennial biological infrastructure matures. The planted perennial footprint exists in year 1 even before it produces food; annual bridge acreage contracts as perennial output rises.</p></div>${renderTimeline(result)}<h3>Canonical mature perennial mix through time</h3>${renderPerennialTimeline()}</div><div><h3>Sunlight → plants → food → people</h3><p>Solar radiation is the continuing primary energy input to biological production. Photosynthesis stores a fraction of it as plant biomass; harvested food contains chemical energy; people require measurable energy.</p><div class="solar-flow"><span>sunlight</span><b>→</b><span>photosynthesis</span><b>→</b><span>edible food energy</span><b>→</b><span>human metabolism</span></div><div class="solar-flow wood"><span>sunlight</span><b>→</b><span>woody biomass</span><b>→</b><span>stored fuel</span><b>→</b><span>winter heat</span></div><p class="small-note">Local numerical solar-conversion values remain unresolved until a defensible Owen Sound irradiation source and transformation chain is established. No photosynthetic efficiency is invented.</p></div></section><section class="section split"><div><h2>Land requirement</h2>${renderLand(result)}</div><div><h3>Housing density ≠ biological carrying capacity</h3><p>Compact housing can reduce building footprint, roads, utilities and transport distances. Residents still require food, materials and energy. When those flows are imported, the productive land and energy flows occur elsewhere.</p><blockquote>You can concentrate houses. You cannot eliminate the land and energy flows that sustain the people inside them.</blockquote><p class="small-note">The hectare graphic shows exclusive blocks plus a hatched ecological overlay. Overlapping functions are not counted a second time.</p></div></section><section class="section" id="sources"><details class="method" open><summary>Sources, assumptions and uncertainty</summary><div class="source-list">${state.contract.sources.map((source: any) => `<p><strong>${esc(source.institution)} · ${esc(source.title)}</strong><br><span>${esc(source.evidence_status)}</span> · <a href="${esc(source.url)}" target="_blank" rel="noreferrer">source / evidence file</a></p>`).join('')}</div><p class="small-note">Public energy and thermal quantities are metric/SI. Source-derived conversions remain inside the canonical calculation layer and are not shown as public units.</p></details></section>`, 'capacity');
}

function cad(value: unknown) { return `$${fmt(value, 2)}`; }
function selectedAffordabilityScenario(): any { return state.contract.site_lease_economics.affordability_scenarios?.find((row: any) => row.id === state.arcScenario) ?? state.contract.site_lease_economics.affordability_scenarios?.find((row: any) => row.id === 'legal_minimum') ?? {id: 'legal_minimum', infrastructure_scenario_id: 'legal_minimum', administration_scenario_id: 'legal_minimum', common_property_operations_scenario_id: 'legal_minimum', vacancy_reserve_rate_annual: 0, insurance_requirement_mode: 'none'}; }
function contractCommonOperationsAnnual(id: string): number { const scenario = state.contract.site_lease_economics.common_property_operations?.find((row: any) => row.id === id); return Number(scenario?.components?.reduce((sum: number, row: any) => sum + Number(row.annual_cad ?? 0), 0) ?? 0); }
function contractCommonOperationsLabour(id: string): number { const scenario = state.contract.site_lease_economics.common_property_operations?.find((row: any) => row.id === id); return Number(scenario?.components?.reduce((sum: number, row: any) => sum + Number(row.resident_labour_hours_year ?? 0), 0) ?? 0); }
function contractAdministrationLabour(id: string): number { return Number(state.contract.site_lease_economics.administration_scenarios?.find((row: any) => row.id === id)?.resident_labour_hours_year ?? 0); }
function affordabilityResult(result: any) {
  const inputs = state.contract.site_lease_economics.default_inputs;
  const affordabilityScenario = selectedAffordabilityScenario();
  const commonAreaGeometry = calculateArcCommonAreaGeometry({...inputs.common_area_geometry, laneway_length_m: state.commonLanewayLength});
  const transition = result.custom.establishment_land?.strategy_comparison?.progressive_handoff;
  const establishment = Number(transition?.establishment_land_requirement_ha ?? result.custom.robust_minimum_area_ha ?? 0);
  const mature = Number(transition?.mature_land_requirement_ha ?? establishment);
  const rows = Array.from({length: Math.max(1, state.communitySize)}, (_, index) => ({household_id: `public-household-${index + 1}`, reserved_land_requirement_ha: establishment}));
  const land = calculateLandLeaseAccounting({
    households: rows,
    common_property_land_ha: commonAreaGeometry.common_property_area_ha,
    land_price_cad_per_ha: state.landPrice,
    ownership: state.landOwnership,
    down_payment_rate: state.landDownPayment / 100,
    interest_rate_annual: state.landInterest / 100,
    amortization_years: state.landAmortization,
    loan_term_years: state.landLoanTerm,
    property_tax_rate_annual: inputs.land_costs.property_tax_rate_annual,
    land_insurance_annual_cad: affordabilityScenario.insurance_requirement_mode === 'none' ? 0 : Number(affordabilityScenario.insurance_annual_cad ?? inputs.land_costs.insurance_annual_cad ?? 0),
    common_land_costs_annual_cad: contractCommonOperationsAnnual(affordabilityScenario.common_property_operations_scenario_id),
    administration_scenario_id: state.administrationScenario,
    fixed_land_reserve_annual_cad: inputs.land_costs.fixed_land_reserve_annual_cad,
    vacancy_reserve_rate_annual: affordabilityScenario.vacancy_reserve_rate_annual,
    allocation_method: 'base_plus_hectare'
  });
  const landRow = land.allocations[0];
  const infrastructureRows = state.contract.site_lease_economics.infrastructure_scale_examples[state.infrastructureScenario] ?? [];
  const infrastructure = infrastructureRows.find((row: any) => row.household_count === state.communitySize) ?? infrastructureRows[0];
  const sharedInfrastructure = Number(infrastructure?.shared_services_monthly_per_household_cad ?? 0);
  const total = landRow.monthly_total_cad + sharedInfrastructure;
  const residentLabourHoursYear = Number(infrastructure?.infrastructure_resident_labour_hours_year ?? 0) + contractAdministrationLabour(state.administrationScenario) + contractCommonOperationsLabour(affordabilityScenario.common_property_operations_scenario_id);
  const infrastructureForDisplay = {...infrastructure, infrastructure_resident_labour_hours_year: residentLabourHoursYear};
  const dwellingContract = state.contract.site_lease_economics.dwelling_cost_model;
  const dwellingBand = dwellingContract?.bands?.central;
  const dwellingFinancingInputs = state.contract.site_lease_economics.dwelling_financing ?? {ownership: 'resident_owned', down_payment_rate: .10, interest_rate_annual: .06, amortization_years: 25};
  const dwellingFinancing = financeCapital({value: Number(dwellingBand?.completed_dwelling_capital_cad ?? 0), ownership: dwellingFinancingInputs.ownership === 'owned_out_right' ? 'owned_out_right' : 'financed', downPaymentRate: dwellingFinancingInputs.down_payment_rate, interestRateAnnual: dwellingFinancingInputs.interest_rate_annual, amortizationYears: dwellingFinancingInputs.amortization_years});
  const completedDwelling = {capital: Number(dwellingBand?.completed_dwelling_capital_cad ?? 0), low: Number(dwellingContract?.completed_dwelling_range_cad?.low ?? 0), high: Number(dwellingContract?.completed_dwelling_range_cad?.high ?? 0), financing: dwellingFinancing, components: dwellingBand?.components ?? []};
  return {result, affordabilityScenario, establishment, mature, land, landRow, sharedInfrastructure, total, infrastructure: infrastructureForDisplay, residentLabourHoursYear, commonLand: land.common_property_land_holding, productiveLand: land.productive_land_charge, financing: land.acquisition.financing, completedDwelling, commonAreaGeometry};
}
