function regionalScenario(): any { const variant = state.contract.regional.grey.site_mix_variants?.[state.mix] ?? state.contract.regional.grey; return variant.scenarios.find((row: any) => row.adoption_rate === state.adoption && row.external_input_condition === state.condition) ?? variant.scenarios.find((row: any) => row.adoption_rate === state.adoption) ?? variant.scenarios[0]; }
function renderRegionalPage() { const scenario = regionalScenario(); const row = scenario.transition_years.find((candidate: any) => candidate.year === 'mature') ?? scenario.transition_years.at(-1); const mixLabels: Array<[string, string]> = [['balanced', 'Balanced 25 / 50 / 25'], ['favourable_heavy', 'More favourable sites'], ['marginal_heavy', 'More marginal sites']]; const proxy = state.contract.regional.land_access_proxy; const proxyNotice = proxy.status === 'available' ? '' : '<p class="notice">The current dwelling-land proxy is unavailable, so regional participation is shown as zero rather than reusing stale estimates. Prepare the Grey land-access report, then rebuild this contract.</p>'; return shell(`<section class="hero compact"><div><p class="eyebrow">Grey County transition</p><h1>What changes when households participate?</h1><p class="lede">This regional view uses the same canonical household/site transitions as the reports. Participation is a share of the current land-access proxy, not all Grey County households.</p></div><div class="hero-callout"><span>Eligibility basis</span><strong>${proxy.eligible_households == null ? 'Unavailable' : `${fmt(proxy.eligible_households)} households`}</strong><small>Garden-scale land-access proxy</small></div></section>${proxyNotice}<section class="section"><div class="controls-row"><label class="control"><span>Participating households</span><select id="adoption">${[0, 10, 25, 50, 75].map((value) => `<option value="${value}" ${value === state.adoption ? 'selected' : ''}>${value}%</option>`).join('')}</select></label>${selectControl('condition', 'External-input condition', Object.entries(state.contract.regional.grey.external_input_conditions).map(([key]) => [key, key.replaceAll('_', ' ')]), state.condition)}${selectControl('mix', 'Site mix', mixLabels, state.mix)}</div><div class="metric-grid four">${metric('Participating households', fmt(row.participating_households, 0))}${metric('People supported', fmt(row.participating_population_people, 0), 'people')}${metric('Productive land', area(row.productive_land_required_ha))}${metric('Regional food demand displaced', energy(row.market_food_demand_displaced_gj_year))}</div><div class="metric-grid four">${metric('Land needed to establish', area(row.establishment_land_requirement_ha))}${metric('Mature land requirement', area(row.mature_land_requirement_ha))}${metric('ARC establishment comparison', area(row.arc_policy_establishment_surplus_or_deficit_ha), row.arc_policy_establishment_surplus_or_deficit_ha >= 0 ? 'surplus' : 'deficit')}${metric('Current exclusive footprint', area(row.productive_land_required_ha))}</div><div class="metric-grid four">${metric('Annual bridge area', area(row.establishment_annual_food_area_ha))}${metric('Mature annual food', area(row.mature_annual_food_area_ha))}${metric('Mature perennial food', area(row.mature_perennial_food_area_ha))}${metric('Woody heating', area(row.woody_heating_area_ha))}</div></section><section class="section tinted"><div class="section-heading"><p class="eyebrow">Through time</p><h2>Adoption is not instant maturity.</h2><p>Annual food demand is bridged first. Perennial production and lower-input labour develop over the canonical transition checkpoints.</p></div><div class="regional-timeline">${scenario.transition_years.map((point: any) => `<article><strong>${point.year === 'mature' ? 'Mature' : `Year ${point.year}`}</strong><b>${area(point.productive_land_required_ha)}</b><span>${fmt(point.labour_hours_total, 0)} labour hours</span><small>${fmt(point.market_food_demand_displaced_gj_year, 0)} GJ market demand displaced</small></article>`).join('')}</div><div class="metric-grid three">${metric('Food coverage change', pct(row.regional_food_coverage_change_percent), 'share of regional demand displaced')}${metric('Exportable surplus', energy(row.mature_exportable_surplus_gj_year), 'separate from self-provision')}${metric('Food-gap replacement remaining', energy(row.food_gap_replacement_requirement_gj_year))}</div></section><section class="section split"><div><h3>What these outputs mean</h3><p>A participating household first reduces its own market demand. Production beyond that household requirement is a separate local surplus flow toward settlements. The model does not combine those flows into one ambiguous self-sufficiency number.</p><p>Favourable, ordinary and marginal shares remain explicit because Grey County does not yet have a validated biological site-capability map.</p></div><div><h3>Energy conditions</h3><p>The biological rows stay canonical. Present, constrained and deeper input conditions are transparent regional overlays for fuel/fertilizer and labour pressure. Their assumptions remain Living Region scenario parameters unless the systemic-energy contract supplies an equivalent measured indicator.</p></div></section>`, 'grey'); }

function renderAdultScaleSection() {
  const scale = state.contract.site_lease_economics.adult_scale;
  if (!scale?.scenarios?.length) return '';
  const rows = scale.scenarios.map((row: any) => `<tr><th scope="row">${fmt(row.adult_residents, 0)}</th><td>${fmt(row.households, 0)}</td><td>${fmt(row.dependent_children_capacity, 0)}</td><td>${area(row.productive_hectares)}</td><td>${area(row.common_hectares)}</td><td>${area(row.total_parcel_hectares)}</td><td>${esc(row.land_market_band)}<br><small>${cad(row.land_price_cad_per_ha)}/ha · ${esc(row.land_price_status.replaceAll('_', ' '))}</small></td><td>${cad(row.site_lease_monthly_cad_per_household)}</td><td>${cad(row.shared_infrastructure_monthly_cad_per_household)}</td><td><strong>${cad(row.combined_land_infrastructure_monthly_cad_per_household)}</strong></td></tr>`).join('');
  const bands = scale.land_market.parcel_size_bands.map((band: any) => `<tr><th scope="row">${esc(band.label)}</th><td>${fmt(band.sample_count, 0)}</td><td>${band.median_price_cad_per_ha == null ? 'Unresolved' : `${cad(band.median_price_cad_per_ha)}/ha`}</td><td>${cad(scale.land_market.planning_curve[band.id])}/ha</td></tr>`).join('');
  return `<section class="section tinted arc-adult-scale" id="community-scale"><div class="section-heading"><p class="eyebrow">ARC community scale</p><h2>Adult-scale planning cases</h2><p>Adult residents are the settlement-scale variable. Household and dwelling count is the resulting arrangement. Except for the one-adult case, each pair of adults is stress-tested as a household designed to support up to three dependent children; this is a capacity case, not a demographic forecast.</p></div><div class="notice"><strong>${esc(scale.family_capacity_standard.label)}:</strong> ${esc(scale.family_capacity_standard.description)}</div><div class="table-scroll"><table class="evidence-table"><thead><tr><th>Adult residents</th><th>Households / dwellings</th><th>Dependent-child capacity</th><th>Productive land</th><th>Common land</th><th>Total parcel</th><th>Land band / assumption</th><th>Site lease / household</th><th>Shared infrastructure / household</th><th>Land + infrastructure / household</th></tr></thead><tbody>${rows}</tbody></table></div><details class="method"><summary>Grey County land price by parcel size</summary><p>The current evidence includes a 2024 Grey County average-quality cropland benchmark of CAD 19,000 per tillable acre from 29 survey responses. It does not provide a size-tagged whole-parcel sale curve. The fallback values below are explicit planning sensitivities and must be replaced or narrowed by manually verified parcel observations.</p><div class="table-scroll"><table class="evidence-table"><thead><tr><th>Parcel band</th><th>Size-tagged observations</th><th>Measured median</th><th>Planning sensitivity</th></tr></thead><tbody>${bands}</tbody></table></div>${scale.land_market.sources.slice(0, 2).map((source: any) => `<p><a href="${esc(source.url)}" target="_blank" rel="noreferrer">${esc(source.institution)}: ${esc(source.title)}</a><br>${esc(source.limitation)}</p>`).join('')}<p class="small-note">${esc(scale.land_market.planning_curve_basis)}</p></details></section>`;
}

function bind() {
  if (state.page === '/arc-affordability') document.querySelector('#land-requirement')?.insertAdjacentHTML('beforebegin', renderAdultScaleSection());
  document.querySelectorAll('[data-nav]').forEach((node) => node.addEventListener('click', (event) => { event.preventDefault(); navigate(routeFromLocation((node as HTMLAnchorElement).pathname)); }));
  document.querySelectorAll('[data-action="add-member"]').forEach((node) => node.addEventListener('click', () => { state.members.push(memberFromProfile({label: 'Household member', age_y: 35, sex: 'female', weight_kg: 65, height_cm: 165, activity: 'low'}, state.members.length)); state.preset = 'custom'; render(); }));
  document.querySelectorAll('[data-action="remove-member"]').forEach((node) => node.addEventListener('click', () => { state.members.splice(Number((node as HTMLElement).dataset.index), 1); state.preset = 'custom'; render(); }));
  document.querySelectorAll('[data-member]').forEach((node) => node.addEventListener('change', () => { const element = node as HTMLInputElement | HTMLSelectElement; const index = Number(element.dataset.member); const field = element.dataset.field as keyof Member; const raw = element.value; (state.members[index] as any)[field] = ['age_y', 'weight_kg', 'height_cm'].includes(field) ? Number(raw) : raw; state.preset = 'custom'; render(); }));
  document.querySelectorAll('[data-action="add-building"]').forEach((node) => node.addEventListener('click', () => { const next = defaultBuilding(); next.id = `building-${state.buildings.length + 1}`; next.label = 'Heated building'; state.buildings.push(next); render(); }));
  document.querySelectorAll('[data-action="remove-building"]').forEach((node) => node.addEventListener('click', () => { state.buildings.splice(Number((node as HTMLElement).dataset.index), 1); render(); }));
  document.querySelectorAll('[data-building]').forEach((node) => node.addEventListener('change', () => { const element = node as HTMLInputElement | HTMLSelectElement; const index = Number(element.dataset.building); const field = element.dataset.field as keyof Building; const value = ['floor_area_m2'].includes(field) ? Number(element.value) : element.value; (state.buildings[index] as any)[field] = value; if (field === 'insulation' && value !== 'custom') state.buildings[index].envelope = {}; render(); }));
  document.querySelectorAll('[data-envelope]').forEach((node) => node.addEventListener('change', () => { const element = node as HTMLInputElement; const index = Number(element.dataset.envelope); state.buildings[index].insulation = 'custom'; state.buildings[index].envelope = {...state.buildings[index].envelope, [element.dataset.field ?? '']: Number(element.value)}; render(); }));
  const preset = $('#preset') as HTMLSelectElement | null; preset?.addEventListener('change', () => { state.preset = preset.value; if (state.preset !== 'custom') state.members = presetMembers(state.preset); render(); });
  for (const id of ['site', 'adoption', 'condition', 'mix']) { const element = $(`#${id}`) as HTMLSelectElement | null; element?.addEventListener('change', () => { const value = element.value; if (id === 'site') state.site = value; if (id === 'adoption') state.adoption = Number(value); if (id === 'condition') state.condition = value; if (id === 'mix') state.mix = value; render(); }); }
  if (state.page === '/arc-affordability') {
    const selectBindings: Array<[string, (value: string) => void]> = [['affordability-site', (value) => { state.site = value; }], ['community', (value) => { state.communitySize = Number(value); }], ['administration', (value) => { state.administrationScenario = value; }], ['land-ownership', (value) => { state.landOwnership = value; }]];
    for (const [id, update] of selectBindings) { const element = $(`#${id}`) as HTMLSelectElement | null; element?.addEventListener('change', () => { update(element.value); render(); }); }
    const affordabilityScenario = $('#affordability-scenario') as HTMLSelectElement | null; affordabilityScenario?.addEventListener('change', () => { const selected = state.contract.site_lease_economics.affordability_scenarios.find((row: any) => row.id === affordabilityScenario.value); state.arcScenario = affordabilityScenario.value; if (selected) { state.infrastructureScenario = selected.infrastructure_scenario_id; state.administrationScenario = selected.administration_scenario_id; } render(); });
    const infra = $('#infrastructure') as HTMLSelectElement | null; infra?.addEventListener('change', () => { state.infrastructureScenario = infra.value; render(); });
    const numeric: Array<[string, (value: number) => void]> = [['land-price', (value) => { state.landPrice = value; }], ['land-interest', (value) => { state.landInterest = value; }], ['land-amortization', (value) => { state.landAmortization = value; }], ['land-term', (value) => { state.landLoanTerm = value; }], ['land-down-payment', (value) => { state.landDownPayment = value; }], ['laneway-length', (value) => { state.commonLanewayLength = value; }]];
    for (const [id, update] of numeric) { const element = $(`#${id}`) as HTMLInputElement | null; element?.addEventListener('change', () => { update(Number(element.value)); render(); }); }
  }
}
function render() { const app = $('#app'); if (!app || !state.contract) return; const params = state.page === '/carrying-capacity' ? scenarioParams() : state.page === '/arc-affordability' ? scenarioParams(true) : new URLSearchParams(state.page === '/grey-county-transition' ? {adoption: String(state.adoption), condition: state.condition, mix: state.mix} : {}); const query = params.toString(); const hash = window.location.hash; history.replaceState({}, '', `${appUrl(state.page)}${query ? `?${query}` : ''}${hash}`); app.innerHTML = state.page === '/grey-county-transition' ? renderRegionalPage() : state.page === '/carrying-capacity' ? renderCapacityPage() : state.page === '/arc-affordability' ? renderAffordabilityPage() : renderLandingPage(); bind(); }
function renderLandingPage() { return shell(`<section class="hero landing-hero"><div><p class="eyebrow">Living Region research interface</p><h1>Explore the physical systems that sustain a region.</h1><p class="lede">Start with the household-scale land, food and heating calculation, then connect that result to transparent ARC land-lease and shared-infrastructure scenarios.</p></div><div class="hero-callout"><span>Canonical model</span><strong>Carrying capacity</strong><small>Shared calculations power the public pages and regional reports.</small></div></section><section class="section landing-links"><a href="${appUrl('/carrying-capacity')}" data-nav><span>01</span><strong>Land & Carrying Capacity</strong><p>Build a household, assign heated buildings and labour, compare perennial evidence, and follow the annual-to-perennial transition.</p><b>Explore the calculator →</b></a><a href="${appUrl('/arc-affordability')}" data-nav><span>02</span><strong>ARC Site + Infrastructure</strong><p>See how the canonical hectares become a separate site lease, shared infrastructure fee and combined land-and-infrastructure charge.</p><b>See the household charge →</b></a><a href="${appUrl('/grey-county-transition')}" data-nav><span>03</span><strong>Grey County Transition</strong><p>Compare 0%, 10%, 25%, 50% and 75% adoption under explicit site mixes and external-input conditions.</p><b>Explore regional scenarios →</b></a></section>`, 'home'); }

window.addEventListener('popstate', () => { state.page = routeFromLocation(); render(); });
function renderCapacityPage() { return renderCapacityPageNew(); }
loadContract().then((contract) => { state.contract = contract; if (!contract.site_classes[state.site]) state.site = 'ordinary_mesic'; if (state.preset !== 'reference_adult_man' && state.preset !== 'custom' && !contract.household_presets.some((row: any) => row.id === state.preset)) state.preset = 'reference_adult_man'; if (!contract.regional.grey.external_input_conditions[state.condition]) state.condition = 'present_external_inputs'; const affordabilityScenarios = contract.site_lease_economics.affordability_scenarios ?? []; if (!affordabilityScenarios.some((row: any) => row.id === state.arcScenario)) state.arcScenario = contract.site_lease_economics.recommended_infrastructure_scenario === 'legal_minimum' ? 'legal_minimum' : affordabilityScenarios[0]?.id; if (!(contract.site_lease_economics.infrastructure_scenarios ?? []).some((row: any) => row.id === state.infrastructureScenario)) state.infrastructureScenario = 'legal_minimum'; if (!(contract.site_lease_economics.administration_scenarios ?? []).some((row: any) => row.id === state.administrationScenario)) state.administrationScenario = 'legal_minimum'; state.members = state.preset === 'custom' && initialMembers?.length ? initialMembers : presetMembers(state.preset); state.buildings = state.preset === 'custom' && initialBuildings?.length ? initialBuildings : [defaultBuilding()]; render(); }).catch((error) => { const app = $('#app'); if (app) app.innerHTML = `<main class="error"><h1>Carrying-capacity contract unavailable</h1><p>${esc(error.message)}</p></main>`; });
